CREATE OR REPLACE FUNCTION public.top_deck(p_world uuid, p_x integer, p_y integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((
    select max(f.level) from floor_tile f
     where f.world_id = p_world and f.x = p_x and f.y = p_y and f.level >= 1
       and bill_done(f.needed) and f.kind <> 'roof'), 0)
$function$
